// In resolver (per-user level)
public class UserType : ObjectType<User>
{
  protected override void Configure(IObjectTypeDescriptor<User> d) {
    d.Field(u => u.Posts)
      .Resolver(async ctx => {
        var userId = ctx.Parent<User>().Id;
        // DataLoader batches these calls
        return await ctx
          .DataLoader<PostByUserIdDataLoader>()
          .LoadAsync(userId);
      });
  }
}

public class DateType : ScalarType<DateOnly>
{
  public DateType() : base("Date") { }

  public override IQueryableParser? Parser => null;

  public override bool IsInstance(object? value) {
    return value is DateOnly;
  }

  public override object? ParseResult(object? resultValue) {
    return resultValue is DateOnly d ? d.ToShortDateString() : null;
  }
}

// Register in Program.cs
services
  .AddGraphQLServer()
  .AddScalarType<DateType>();
